SELECT bs.bldg_id, bs.county, bs.state FROM comstock_amy2018_r2_2025_md_agg_by_state_and_county_parquet AS bs WHERE bs.upgrade IN (1, 2, 3) AND bs.applicability = true GROUP BY bs.bldg_id, bs.county, bs.state HAVING count(distinct(CASE WHEN (bs.upgrade IN (1)) THEN bs.upgrade END)) = 1 AND count(distinct(CASE WHEN (bs.upgrade IN (2, 3)) THEN bs.upgrade END)) >= 1